	 ('0002-2023-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE BARRANCA','00003-2025-OEFA/DSIS','2025-02-28','2025-I01-009230','ACTIVO','Realizar las acciones de esparcido, compactación y cobertura de los residuos sólidos en las coordenadas UTM zona 18L 8822515N 189242E, 8822517N 189238E, 8822415N 189184E, con una frecuencia mínima de tres (3) veces a la semana.','00000012512','20250300001',2.2,NULL,NULL,'ACTIVO'),
	 ('0021-2023-DSEM-CMIN','EMPRESA ADMINISTRADORA CERRO S.A.C.','00034-2025-OEFA/DSEM','2025-01-29','2025-I01-004234','ACTIVO','Remediar el suelo por donde ha discurrido el flujo de agua ácida proveniente del rajo RP-219. Para la remediación se realizarán muestreos previos y posteriores a la medida, a fin de verificar su eficacia.','00002332512','2025020000003',32,NULL,NULL,'ACTIVO'),
	 ('0021-2023-DSEM-CMIN','EMPRESA ADMINISTRADORA CERRO S.A.C.','00034-2025-OEFA/DSEM','2025-01-29','2025-I01-004234','ACTIVO','Realizar la caracterización geoquímica de los rajos RP-213 y RP-219, así como del material de relleno utilizado para el cierre de los rajos antes descritos, con la finalidad de determinar el origen de la generación de aguas ácidas.','00002342512','2025020000003',14.02,NULL,NULL,'ACTIVO'),
	 ('0021-2023-DSEM-CMIN',NULL,'00034-2025-OEFA/DSEM','2025-01-29','2025-I01-004234','ACTIVO','Remediar el suelo por donde ha discurrido el flujo de agua ácida proveniente del rajo RP-219. Para la remediación se realizarán muestreos previos y posteriores a la medida, a fin de verificar su eficacia.','00002352512','2025020000003',32,NULL,NULL,'INACTIVO'),
	 ('0156-2022-DSEM-CMIN','ARUNTANI S.A.C.','00096-2025-OEFA/DSEM','2025-04-28','2025-I01-018669','ACTIVO','Captar y tratar las descargas de agua de las pozas de subdrenajes N° 1 (SW-08) y N° 2 (SW-09) del pad de lixiviación Jessica, a fin de cumplir con los Estándares Nacionales de Calidad Ambiental para Agua establecidos en el Decreto Supremo N° 015-2015-MINAM y evitar que sigan alterando la calidad del agua superficiales y de las comunidades hidrobiológicas de la quebrada Lluchusani.','00003482512','20250400065',76,NULL,NULL,'ACTIVO'),
	 ('0148-2024-DSEM-CMIN','ARUNTANI S.A.C.','00106-2025-OEFA/DSEM','2025-05-09','2025-I01-020540','ACTIVO','Captar el agua de contacto del depósito de desmonte ESP-ARI-1 y derivarla a la planta de tratamiento STAA Wetland Sur, a fin de que cumplan con los LMP previo a su descarga a la quebrada Apostoloni. La captación se deberá realizar de tal modo, que no exista agua de contacto ingresando hacia el canal de agua de no contacto de dicho componente, a fin de que no se afecte la quebrada Apostoloni, la flora y fauna cercanas, ni la salud de las personas','00005032512','20250500016',12.15,NULL,NULL,'ACTIVO'),
	 ('0197-2024-DSEM-CMIN','ARUNTANI S.A.C.','00107-2025-OEFA/DSEM','2025-05-09','2025-I01-020542','ACTIVO','Retirar la tubería desde su origen y captar el agua de contacto hacia la poza 90 000 para su respectivo tratamiento en el STAA Wetland Sur a fin de que dichas aguas cumplan con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM','00005092512','20250500017',64,NULL,NULL,'ACTIVO'),
	 ('0192-2023-DSEM-CMIN','MINISTERIO DE ENERGIA Y MINAS','00097-2025-OEFA/DSEM','2025-04-29','2025-I01-018937','ACTIVO','Captar y tratar el efluente proveniente de la bocamina BOC-LN-LL-15 que descarga al suelo, de forma tal que éste no supere los Límites Máximos Permisibles establecidos en el Decreto Supremo Nº 010-2010-MINAM.','00004042512','20250400077',100,NULL,NULL,'ACTIVO'),
	 ('0185-2024-DSEM-CMIN','ARUNTANI S.A.C.','00105-2025-OEFA/DSEM','2025-05-08','2025-I01-020182','ACTIVO','Retirar la tubería corrugada, ubicada en la coordenada UTM WGS 84 19: 372020 E, 8168172 N y captar el flujo de agua de contacto proveniente del depósito de desmonte y derivarla a la planta de tratamiento STAA Wetland Sur, a fin de que cumpla con los LMP.','00004402512','20250500008',100,NULL,NULL,'ACTIVO'),
	 ('0192-2023-DSEM-CMIN','MINISTERIO DE ENERGIA Y MINAS','00097-2025-OEFA/DSEM','2025-04-29','2025-I01-018937','ACTIVO','Captar y tratar los efluentes provenientes del depósito de relaves RELAV-MO-LL-4, de forma tal que éstos no superen los Límites Máximos Permisibles establecidos en el Decreto Supremo Nº 010-2010-MINAM antes de ser descargado al rio Hualgayoc.','00004052512','20250400077',100,NULL,NULL,'ACTIVO');
INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0155-2024-DSEM-CMIN','ARUNTANI S.A.C.','00102-2025-OEFA/DSEM','2025-05-06','2025-I01-019776','ACTIVO','Captar el agua de contacto del depósito de desmonte INF-1, INF-2, INF-3, ESP-ARI-1 y ESP-ARI-11 y derivarla a la planta de tratamiento STAA Wetland Sur, a fin de que cumplan con los LMP. La captación se deberá realizar de tal modo, que ya no existan afloramientos hacia la quebrada S/N 2, ni flujos de agua de contacto hacia el canal de agua de no contacto de dicho componente.','00004382512','20250500007',5.4,NULL,NULL,'ACTIVO'),
	 ('0155-2024-DSEM-CMIN','ARUNTANI S.A.C.','00102-2025-OEFA/DSEM','2025-05-06','2025-I01-019776','ACTIVO','Reparar el canal de agua de no contacto del depósito de desmonte zona norte, desde la coordenada UTM WGS 84 8168352 N; 372459 E, hasta UTM WGS 84 8168241 N; 372256 E (aproximadamente 234 m) de forma que no existan grietas que permitan el ingreso cualquier flujo de agua de contacto hacia dicho canal. ','00004392512','20250500007',3.24,NULL,NULL,'ACTIVO'),
	 ('0340-2023-DSEM-CHID','PETROLEOS DEL PERU PETROPERU SA','00095-2025-OEFA/DSEM','2025-04-28','2025-I01-018655','ACTIVO','Realizar la limpieza total del área afectada por el derrame de petróleo crudo ocurrido el 28 de agosto de 2023 en el km 24+341 del tramo I del Oleoducto Norperuano.','00003692512','20250400070',64,NULL,NULL,'ACTIVO'),
	 ('0174-2024-DSEM-CMIN','ARUNTANI S.A.C.','00100-2025-OEFA/DSEM','2025-05-05','2025-I01-019556','ACTIVO','Presentar ante la Autoridad Certificadora, la modificación de la Cuarta Modificación del Plan de Cierre de Minas de la unidad fiscalizable Florencia-Tucari, aprobada mediante Resolución Directoral N° 286-2016/MEM-DGAAM, a fin de que se incorporen aquellos componentes implementados o modificados con posterioridad a la emisión de la Resolución Directoral N° 166-2019-MINEM/DGM del 13 de septiembre de 2019, así como los cambios en el sistema de tratamiento y bombeo de lodos, y el cambio de la funcionalidad del tajo para la disposición de lodos provenientes del sistema de tratamiento de agua ácida del tajo.','00004292512','20250500005',100,NULL,NULL,'ACTIVO'),
	 ('0019-2022-DSEM-CMIN','MINERA CHINALCO PERÚ S.A.','00109-2025-OEFA/DSEM','2025-05-13','2025-I01-021212','ACTIVO','Minera Chinalco Perú S.A. no ha cumplido con ejecutar el cierre, de la ampliación (áreas divergentes) de los componentes mineros que fueron aprobadas, en el Estudio de Impacto Ambiental del Proyecto de Explotación Toromocho, aprobado con Resolución Directoral N° 411-2010-MEM/AAM, denominados como Depósito de Mineral de Baja Ley Suroeste y Depósito de Mineral de Baja Ley, toda vez que: •	No habría cumplido con ejecutar las actividades de Cierre del Área divergente 1 de acuerdo a lo aprobado en el ETC, respecto al ítem 1.3 Manejo de agua, en el extremo referido al ingreso de flujos de agua al sistema de drenaje de la operación, para ser conducidos de manera regulada hacia el túnel Kingsmill. •	No habría cumplido con ejecutar las actividades de Cierre del Área divergente 2 de acuerdo a lo aprobado en el ETC, en el extremo referido a los ítems 1.2 Estabilización Física y 1.3 Manejo de agua, al no haber acreditado el retiro total del mineral de baja ley, ni haber acreditado la procedencia del material de relleno de la parte baja ubicada al Este del Área divergente 2. 
•	No ha implementado el canal perimetral, la caja colectara N° 2 y el colchón de mampostería N° 2, ubicados en el extremo Norte del Área divergente 2, conforme al diseño aprobado en el ETC.','00005262512','20250500026',4.48,NULL,NULL,'ACTIVO'),
	 ('0213-2024-DSEM-CMIN','ARUNTANI S.A.C.','00117-2025-OEFA/DSEM','2025-05-22','2025-I01-022738','ACTIVO','Retirar la tubería desde su origen hasta la ubicación de la misma en coordenada UTM WGS 84 19: 372029 E, 8168184, para luego captar el agua de contacto ESP-ARI-1 hacia el sistema de tratamiento de agua ácida del Tajo (STAA Wetland Sur) a fin de que cumpla con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM en el punto PS-02 (antes de ser descargado a la quebrada Apostoloni).','00005982512','20250500055',100,NULL,NULL,'ACTIVO'),
	 ('0001-2025-DSEM-CMIN','ARUNTANI S.A.C.','00111-2025-OEFA/DSEM','2025-05-16','2025-I01-021866','ACTIVO','“Retirar la tubería desde su origen hasta la ubicación de la misma en coordenadas UTM WGA 84 19: 371659 E, 8167196 N, para luego captar el agua de contacto ESP-ARI-1P y derivarla hacia el sistema de tratamiento de agua ácida (STTA Wetland Sur), a fin de que cumpla con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM en el punto PS-02 (antes de ser descargado a la quebrada Apostoloni)”.','00005442512','20250500038',100,NULL,NULL,'ACTIVO'),
	 ('0023-2022-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE REQUENA','00003-2025-OEFA/ODES-LOR','2025-04-30','2025-I13-019347','ACTIVO','Medida Preventiva N° 6

Implementar un sistema de manejo de lixiviados en el Botadero carretera Requena – Yaquerana, que contemple:
ii) Implementación y construcción de una poza de almacenamiento de lixiviados, la cual debe estar impermeabilizada con geomembrana, provista de una cubierta (techo) y un canal perimetral pluvial para evitar el ingreso del agua de lluvia. **

** La poza de lixiviados, debe ser ubicada al noreste del botadero, es decir en la parte de menor elevación, para permitir que los lixiviados fluyan por gravedad hacia la poza de almacenamiento.
','00006482512','20250500069',2,NULL,NULL,'ACTIVO'),
	 ('0023-2022-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE REQUENA','00003-2025-OEFA/ODES-LOR','2025-04-30','2025-I13-019347','ACTIVO','Medida Preventiva N° 6

Implementar un sistema de manejo de lixiviados en el Botadero carretera Requena – Yaquerana, que contemple:
iii) Implementación de un canal de interceptación de agua pluvial, para evitar el ingreso de agua de lluvia al ADRSM. ***

***El canal perimetral de interceptación de agua de lluvia, debe ser ubicado al noroeste del botadero, es decir, en la zona de mayor elevación, con el fin de interceptar el agua de lluvia antes de ingresar al área del botadero.

Finalmente, a fin de evitar el desborde de lixiviados de la poza de almacenamiento, se deberá realizar la recirculación periódica de los lixiviados hacia el botadero.
','00006492512','20250500069',2,NULL,NULL,'ACTIVO'),
	 ('0023-2022-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE REQUENA','00003-2025-OEFA/ODES-LOR','2025-04-30','2025-I13-019347','ACTIVO','Medida Preventiva N° 6
Implementar un sistema de manejo de lixiviados en el Botadero carretera Requena – Yaquerana, que contemple:
i) Implementación de drenes para la captación de lixiviados en todo el perímetro del área con residuos sólidos dispuestos. *

*Los canales de los drenes perimetrales de captación de lixiviados deberán tener un ancho de 0.40 m y una profundidad de 0.40 m con una pendiente mínima de 2% que garantice que los lixiviados fluyan hacia la poza de almacenamiento.

Cabe precisar que los drenes perimetrales de captación de lixiviados deberán estar conectados a la poza de almacenamiento de lixiviados a través de una tubería de 4 o 6 pulgadas de diámetro.


','00006472512','20250500069',2,NULL,NULL,'ACTIVO');
INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0044-2025-DSEM-CMIN','ARUNTANI S.A.C.','00112-2025-OEFA/DSEM','2025-05-16','2025-I01-021867','ACTIVO','“Captar el flujo de agua de contacto proveniente del depósito de desmonte, que descarga en la quebrada s/n 2, ubicado en la coordenada UTM WGS 84 Zona 19: 372314 E, 8168290 N a 4874 m.s.n.m. y derivarlo a la planta de tratamiento STAA Wetland Sur, a fin de que cumpla con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM”','00005432512','20250500037',100,NULL,NULL,'ACTIVO'),
	 ('0213-2024-DSEM-CMIN','ARUNTANI S.A.C.','00117-2025-OEFA/DSEM','2025-05-22','2025-I01-022738','ACTIVO','Identificar en campo el origen de la tubería ubicada en la coordenada UTM WGS 84 19: 372029 E, 8168184 N.','00005972512','20250500055',100,NULL,NULL,'ACTIVO'),
	 ('0041-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL LA MATANZA','00002-2025-OEFA/ODES-PIU','2025-05-26','2025-I17-007473','ACTIVO','MEDIDA PREVENTIVA N°3
Realizar el esparcido, nivelación, compactación y cobertura de los residuos sólidos que se encuentran fuera del sector definido en la Medida Preventiva N° 2 de la presente acta. La cobertura debe realizarse con capas de material de la zona, con un espesor no menor a 0.20 m, para asegurar su correcto confinamiento.','00006702512','20250500075',1.6,NULL,NULL,'ACTIVO'),
	 ('0041-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL LA MATANZA','00002-2025-OEFA/ODES-PIU','2025-05-26','2025-I17-007473','ACTIVO','MEDIDA PREVENTIVA N°2.
Realizar la descarga, esparcido, nivelación, compactación y cobertura de los residuos sólidos que ingresan diariamente al ADRS “Botadero Municipal”, únicamente en el sector ubicado en las coordenadas UTM 599967 E, 9422790 N, considerando las siguientes actividades:

(…)

Realizar las operaciones de esparcimiento, nivelación, compactación y cobertura de los residuos sólidos deberán realizarse al menos una (01) vez por semana Considerando una capa de cobertura de mínimo 0.2 m. de espesor.

Es preciso señalar que el área (m2 o Ha) del sector que se utilizará para la descarga de residuos sólidos deberá definirse en función de la cantidad estimada de residuos que se recibirán durante el período de esta medida.','00006692512','20250500075',1.6,NULL,NULL,'ACTIVO'),
	 ('0001-2024-ODES-MOQ','EMPRESA DE TRANSPORTE NACIONAL E INTERNACIONAL ATB SRL','00006-2025-OEFA/ODES-MOQ','2025-05-28','2025-I15-023513','ACTIVO','La EMPRESA DE TRANSPORTE NACIONAL E INTERNACIONAL A.T.B.  S.R.L. no realizó el transporte ni disposición final de los residuos sólidos generados como consecuencia de las acciones de limpieza de la emergencia ambiental, además, de no remitir el informe técnico que detallen las actividades realizadas para el cumplimiento de la medida administrativa N° 6, ordenada el 28 de diciembre de 2023 correspondiente al expediente N° 0041-2023-ODES-MOQ.','00008422512','20250500107',1.44,NULL,NULL,'ACTIVO'),
	 ('0002-2025-DSEM-CMIN','ARUNTANI S.A.C.','00121-2025-OEFA/DSEM','2025-05-29','2025-I01-023818','ACTIVO','Redireccionar la tubería de HDPE, ubicada en la coordenada UTM WGS 84 19: 372584 E, 8167114 N (ESP-ARI-3P), hacia el canal de coronación lado sur para que el agua de contacto ingrese a la poza auxiliar intermedia del STAA Wetland Sur, a fin de que cumpla con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM en el punto PS-02 antes de ser descargado a la quebrada Apostoloni.','00008432512','20250500108',100,NULL,NULL,'ACTIVO'),
	 ('0078-2025-DSEM-CMIN','ARUNTANI S.A.C.','00130-2025-OEFA/DSEM','2025-06-05','2025-I01-025035','ACTIVO','Captar el agua de contacto del depósito de desmonte (ESP-ARI-6, ESP-ARI-7, ESP-ARI-8 y ESP-ARI-5) y derivarla a la planta de tratamiento STAA Wetland Sur, a fin de que cumplan con los LMP 2010 previo a su descarga a la quebrada Apostoloni.  La captación se deberá realizar de tal modo, que no exista agua de contacto ingresando hacia el canal de agua de no contacto de dicho componente, a fin de que no se afecte la quebrada Apostoloni, la flora y fauna cercanas ni la salud de las personas.','00010152512','20250600008',64,NULL,NULL,'ACTIVO'),
	 ('0045-2025-DSEM-CMIN','ARUNTANI S.A.C.','00122-2025-OEFA/DSEM','2025-06-02','2025-I01-024216','ACTIVO','Extraer, mediante el uso de una cisterna, el agua contenida en la poza revestida con geomembrana del botadero Norte ubicada en la coordenada UTM WGS84 Zona 19K 388520E y 8159767N; y posterior a ello, tratarla de manera externa.','00009942512','20250600001',31.5,NULL,NULL,'ACTIVO'),
	 ('0256-2021-DSEM-CHID','PETROLEOS DEL PERU PETROPERU SA','00125-2025-OEFA/DSEM','2025-06-02','2025-I01-024409','ACTIVO','Limpiar y descontaminar la totalidad del suelo contaminado producto de la infiltración del petróleo crudo derramado en el Km 193+000 del Ramal Norte del ONP y que equivale a aproximadamente 3 869 m3 de suelos contaminados con una presencia de hidrocarburo, que va desde 1.5% hasta 3.5%, es decir de 15,000 a 35,000 mg/kg de TPH.
Para ejecutar la presente obligación, el administrado deberá presentar un Plan de trabajo que contenga un cronograma de actividades. El cronograma de actividades debe sustentarse en la información obtenida en los estudios realizados por la empresa Kanay S.A.C., y presentado por Petróleos del Perú - Petroperú S.A. al OEFA con el nombre de informe de “Evaluación del Área Impactada” - “Servicio Técnico Especializado de Limpieza, Remediación Ambiental y Disposición Final de Residuos Sólidos Generados en las Áreas Afectadas por el Derrame de Petróleo Crudo Ocurrido en el km 193 del Oleoducto Ramal Norte del Oleoducto Norperuano” o en un estudio complementario o un nuevo estudio especializado que actualice dicha información.','00009962512','20250600003',80,NULL,NULL,'ACTIVO'),
	 ('0048-2025-DSEM-CELE','EMP REG DE SERV PUBLICO DE ELECTRICIDAD','00123-2025-OEFA/DSEM','2025-06-02','2025-I01-024234','ACTIVO','Limpieza total del área afectada, dentro de la central y en el terreno colindante a la C.T. El estrecho, donde se verificó la afectación al componente suelo, como consecuencia del vertimiento de residuos líquidos oleosos y aguas residuales domésticas provenientes de la poza de agua, poza API y poza séptica. 

El administrado deberá realizar la disposición final de los residuos sólidos peligrosos generados (suelo contaminado), como consecuencia del vertimiento de los residuos líquidos oleosos y aguas residuales domésticas provenientes de la poza de agua, poza API y poza séptica, a través de una Empresa Operadora de Residuos Sólidos registrada en el MINAM. 

Además, deberá realizar el monitoreo ambiental de calidad de suelo en los lugares donde se verificaron los vertimientos de los residuos líquidos oleosos y residuos domésticos provenientes de las pozas mencionadas.','00009972512','20250600004',5.67,NULL,NULL,'ACTIVO');
INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0048-2025-DSEM-CELE','EMP REG DE SERV PUBLICO DE ELECTRICIDAD','00123-2025-OEFA/DSEM','2025-06-02','2025-I01-024234','ACTIVO','Ampliar la capacidad de las pozas verificadas durante la acción de supervisión, a efectos de evitar el rebose de los fluidos contenidos en dichas pozas.','00009982512','20250600004',10.08,NULL,NULL,'ACTIVO'),
	 ('0115-2023-DSAP-CIND','ERSA TRANSPORTES Y SERVICIOS SRL','00033-2025-OEFA/DSAP','2025-05-30','2025-I01-024152','ACTIVO','Efectuar la Actualización del PAMA aprobado con Oficio N° 07122-2009-PRODUCE/DVMYPE-I/DGI-DAAI, incluyendo su Programa de Manejo Ambiental, a efectos que PRODUCE evalúe los aspectos detallados en el Cuadro N° 01 de la presente resolución y establezca medidas de manejo ambiental permanentes para los riesgos identificados, a fin de que estos sean implementados en plazos oportunos y acordes con la protección ambiental.
Para ello, el administrado en su solicitud de actualización del PAMA deberá proponer alternativas de manejo ambiental y sustentar técnicamente su eficiencia a PRODUCE.
En caso el trámite de lo ordenado en la presente resolución no concluya con la aprobación de la Autoridad Certificadora por causa imputable al administrado, la medida administrativa se considerará incumplida.','00009992512','20250600005',5.76,NULL,NULL,'ACTIVO'),
	 ('0015-2022-DSEM-CMIN','COMPAÑIA MINERA SANTANDER SOCIEDAD ANONIMA CERRADA','00129-2025-OEFA/DSEM','2025-06-04','2025-I01-024803','ACTIVO','“Implementar cada una de las propuestas de la mejora tecnológica del STAM existente de interior mina y en superficie, de acuerdo a lo establecido en el Tercer Informe Técnico Sustentatorio de la Primera Modificación del Estudio de Impacto Ambiental detallado 2019 de la Unidad Minera Santander, aprobado mediante Resolución Directoral N° 0058-2022-SENACE-PE/DEAR del 11 de abril de 2022, a fin de que su efluente cumpla con los Límites Máximos Permisibles establecidos en el Decreto Supremo N° 010-2010-MINAM antes de ser descargado al río Baños en el punto de vertimiento VR-TP-01”.','00010002512','20250600006',64,NULL,NULL,'ACTIVO'),
	 ('0003-2025-DSEM-CMIN','ARUNTANI S.A.C.','00132-2025-OEFA/DSEM','2025-06-09','2025-I01-025636','ACTIVO','Paralizar la fuga de agua de contacto denominada ESP-ARI-3A procedente de la tubería corrugada ubicada en UTM WGS 84 Zona 19: 372050 E, 8168154 N.','00010232512','20250600012',100,NULL,NULL,'ACTIVO'),
	 ('0045-2025-DSEM-CMIN','ARUNTANI S.A.C.','00122-2025-OEFA/DSEM','2025-06-02','2025-I01-024216','ACTIVO','Realizar el mantenimiento del sistema de tratamiento pasivo del botadero Norte para que afronte el periodo de lluvia del 2025 (enero, febrero, marzo y abril). Para ello deberá considerar como mínimo las siguientes actividades. •	Disponer tanques de plástico nuevos, con una adecuada dosificación de cal.
•	Implementar un soporte estable en las bases de los tanques de plástico nuevos.
•	Implementar en los tanques de plástico nuevos un sistema de conexión continuo, de forma que se demuestre que no existen tuberías y valvular deterioradas, ni obstruidas. Realizar muestreos del agua tratada y comparar los resultados de pH y metales con los valores establecidos en el Decreto Supremo N° 010-2010-MINAM.','00009952512','20250600001',31.5,NULL,NULL,'ACTIVO'),
	 ('0148-2024-DSEM-CMIN','ARUNTANI S.A.C.','00140-2025-OEFA/DSEM','2025-06-19','2025-I01-027218','ACTIVO','Captar el agua de contacto del depósito de desmonte ESP-ARI-1 y derivarla a la planta de tratamiento STAA Wetland Sur, a fin de que cumplan con los LMP previo a su descarga a la quebrada Apostoloni. La captación se deberá realizar de tal modo, que no exista agua de contacto ingresando hacia el canal de agua de no contacto de dicho componente, a fin de que no se afecte la quebrada Apostoloni, la flora y fauna cercanas, ni la salud de las personas.','00011462512','20250600044',12.15,NULL,NULL,'ACTIVO'),
	 ('0089-2021-DSEM-CMIN','COMPAÑIA MINERA KOLPA S.A.','00142-2025-OEFA/DSEM','2025-06-20','2025-I01-027494','ACTIVO','Remediar: El suelo donde se identificó la disposición de desmonte adyacente a la Galería 400 Nivel 4605 (Bocamina Nivel 4606) ubicada en las coordenadas UTM (Datum WGS 84, zona 18L): 502131E, 8554227N. Para la remediación se realizará muestreos previos y posteriores a la implementación de la medida a fin de verificar su eficacia.','00012002512','20250600058',27,NULL,NULL,'ACTIVO'),
	 ('0133-2023-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE PISCO','00008-2025-OEFA/ODES-ICA','2025-04-29','2025-I09-018891','ACTIVO','Con referencia a la Obligación N° 5 (O.5), consignada en la Ficha de Obligaciones
(Anexo 1 del Acta de Supervisión), correspondiente a la Medida Preventiva con
Expediente N° 0133-2023-DSIS-CRES.
Obligación:
Solo se debe realizar la descarga de los residuos sólidos Municipales en las
instalaciones del “Botadero Fundo Santa Martha”, por ende, la municipalidad
deberá identificar y delimitar un área específica en el área degradada, para
realizarla descarga diaria de los residuos sólidos municipales.','00011162512','20250600039',1.93,NULL,NULL,'ACTIVO'),
	 ('0133-2023-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE PISCO','00008-2025-OEFA/ODES-ICA','2025-04-29','2025-I09-018891','ACTIVO','Medida preventiva N° 6
Con referencia a la Obligación N° 10 (O.10), y Obligación N° 11 (O.11),
consignadas en la Ficha de Obligaciones (Anexo 1del Acta de Supervisión),
correspondiente a la Medida Preventiva con Expediente N° 0133-2023-DSISCRES.
Obligación:
“Realizar la Identificación y mitigación de las zonas y/o puntos de emanación de
humos y gases generados a partir de la combustión de los residuos sólidos
dispuestos en el “Botadero Fundo Santa Martha”, para esto se deberá:
1. Identificar las zonas y/o puntos de emanación de humos y gases: así como,
realizar la georreferenciación y cálculo de las áreas respectivas.
2. Realizar la mitigación de las zonas y/o puntos de emanación de humos y gases,
para lo cual, se deberá efectuar las siguientes acciones:
i. Aislar la zona y/o punto de emanación de humos y gases identificados.
ii. Realizar el esparcido mediante herramientas y/o maquinaria (dependiendo del
punto).
iii. Realizar la cobertura de la zona y/o punto de emanación de humos y gases,
con material de la zona considerando una capa de 0.20 m. de espesor.','00011172512','20250600039',1.93,NULL,NULL,'ACTIVO'),
	 ('0089-2021-DSEM-CMIN','COMPAÑIA MINERA KOLPA S.A.','00142-2025-OEFA/DSEM','2025-06-20','2025-I01-027494','ACTIVO','Remediar: El suelo por donde discurrieron los flujos de agua proveniente de las labores subterráneas, es decir, los efluentes de la Bocamina B-4555. Para la remediación se realizará muestreos previos y posteriores a la implementación de la medida para verificar su eficacia”.','00011982512','20250600058',27,NULL,NULL,'ACTIVO');
INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0002-2022-DSAP-CIND','QUIMPAC S.A.','00036-2025-OEFA/DSAP','2025-06-19','2025-E01-056842','ACTIVO','Medida administrativa N° 8
Planta Oquendo 2 – Sistema ecualizador
Implementar dos (2) analizadores en línea de Hg a la salida del colector general de la Planta Oquendo 2 (sistema de tanques ecualizadores), donde confluyen todos los efluentes de la Planta Oquendo 2, a fin de garantizar que los efluentes tratados sean descargados al emisor submarino con una concentración igual o menor al valor límite de 0,01 mg/L (valor establecido como obligación en sus IGAS aprobados). El segundo analizador tendrá la calidad de “stand by o respaldo” y entrará en funcionamiento, cuando el otro no opere, ya sea por razones de mantenimiento, calibración u otros.
Los analizadores automatizados deberán instalarse y funcionar conforme a las especificaciones técnicas (ver tabla Nº 14.1 de la Resolución Directoral III).','00012272512','20250600060',75,NULL,NULL,'ACTIVO'),
	 ('0048-2024-DSEM-CHID','PETROLEOS DEL PERU PETROPERU SA','00144-2025-OEFA/DSEM','2025-06-23','2025-I01-027711','ACTIVO','“Declarar que Petróleos del Perú – Petroperú S.A. ha incumplido la medida
preventiva N° 1 ordenada en la Resolución N° 00199-2023-OEFA/DSEM, referida a realizar
la limpieza del área total impactada –5610 m2 aproximadamente, que comprende el área
inicial y el área extendida– por el derrame de petróleo crudo ocurrido el 29 de julio de
2022 en el Km 235+239 del Tramo I del Oleoducto Norperuano”.','00012762512','20250600065',5.4,NULL,NULL,'ACTIVO'),
	 ('0440-2024-DSAP-CIND','HORNOS ELECTRICOS PERUANOS S.A.','00039-2025-OEFA/DSAP','2025-06-25','2025-I01-028176','ACTIVO','Efectuar la Actualización del DAP aprobado con Oficio N°257-2002- MITINCI/VMI/DNI/DAAM, incluyendo su Programa de Manejo Ambiental, a efectos que PRODUCE evalúe los aspectos detallados en el Cuadro N° 05 de la presente resolución y establezca medidas de manejo ambiental permanentes para los riesgos identificados, a fin de que estos sean implementados en plazos oportunos y acordes con la protección ambiental.
Para ello, el administrado en su solicitud de actualización del DAP deberá proponer alternativas de manejo ambiental y sustentar técnicamente su eficiencia a PRODUCE.
En caso el trámite de lo ordenado en la presente resolución no concluya con la aprobación de la Autoridad Certificadora por causa imputable al administrado, la medida administrativa se considerará incumplida.','00013202512','20250600080',10.368,NULL,NULL,'ACTIVO'),
	 ('0089-2021-DSEM-CMIN','COMPAÑIA MINERA KOLPA S.A.','00142-2025-OEFA/DSEM','2025-06-20','2025-I01-027494','ACTIVO','Remediar: El suelo donde se ubicaron los depósitos de desmonte DD-16, DD-27 y DD-38. Para la remediación se realizará muestreos previos y posteriores a la implementación de la medida para verificar su eficacia.','00011992512','20250600058',48,NULL,NULL,'ACTIVO'),
	 ('0002-2022-DSAP-CIND','QUIMPAC S.A.','00036-2025-OEFA/DSAP','2025-06-19','2025-E01-056842','ACTIVO','Medida administrativa N° 5
Planta Oquendo 1 – colector general de efluentes
Implementar dos (2) analizadores en línea de Hg para el colector general, donde confluyen todos efluentes de la Planta Oquendo 1, a fin de garantizar que estos tengan concentraciones menores a 0,01 mg/L (mercurio) antes de su vertimiento al mar de la bahía del Callao. El segundo analizador tendrá la calidad de “stand by o respaldo” y entrará en funcionamiento, cuando el otro no opere, ya sea por razones de mantenimiento, calibración u otros. Los analizadores en línea deberán instalarse y funcionar conforme a las especificaciones técnicas (ver tabla Nº 13.1 de la Resolución Directoral III).','00012262512','20250600060',75,NULL,NULL,'ACTIVO'),
	 ('0169-2023-DSEM-CMIN','CORPORACION MINERA CENTAURO S.A.C.','00149-2025-OEFA/DSEM','2025-06-30','2025-I01-028746','ACTIVO','“Realizar el desagüe del agua ácida del tajo Quicay hacia las plantas de tratamiento de agua ácida de la unidad minera Quicay, antes de ser descargada al cuerpo receptor que debe cumplir con los Límites Máximos Permisibles establecidos en el Decreto Supremo N° 010-2010-MINAM, a fin de evitar la afectación del agua subterránea”.','00014482512','20250600112',37.5,NULL,NULL,'ACTIVO'),
	 ('0169-2023-DSEM-CMIN','CORPORACION MINERA CENTAURO S.A.C.','00149-2025-OEFA/DSEM','2025-06-30','2025-I01-028746','ACTIVO','“Implementar mejoras para la eficiencia e incrementar la capacidad de las plantas de tratamiento de agua residual industrial NCD y SFNE-1, utilizadas para el tratamiento de agua ácida, a fin de reducir el tiempo de exposición del agua ácida del tajo.”','00014492512','20250600112',37.5,NULL,NULL,'ACTIVO'),
	 ('0024-2022-DSIS-CRES','MUNICIPALIDAD PROV. BELLAVISTA','00004-2025-OEFA/ODES-SAM','2025-06-27','2025-I24-028626','ACTIVO','Implementar las operaciones de nivelación, compactación y cobertura diaria de los residuos sólidos en el frente de trabajo de las trincheras con capas de material de la zona de un espesor no menor de 0.20 m que permita su correcto confinamiento.','00014272512','20250600105',1,NULL,NULL,'ACTIVO'),
	 ('0150-2025-DSAP-CIND','MULTISERVICIOS PIRAMIDES DE ORO S.R.L.','00040-2025-OEFA/DSAP','2025-06-30','2025-I01-028903','ACTIVO','Efectuar la Actualización del DAA aprobado con Resolución Directoral N° 334-2019-PRODUCE/DVMYPE-I/DGAAMI, incluyendo su Programa de Manejo Ambiental, a efectos que PRODUCE evalúe los aspectos detallados en el Cuadro N° 02 de la presente resolución y establezca medidas de manejo ambiental permanentes para los riesgos identificados, a fin de que estos sean implementados en plazos oportunos y acordes con la protección ambiental.
Para ello, el administrado en su solicitud de actualización del DAA deberá proponer alternativas de manejo ambiental y sustentar técnicamente su eficiencia a PRODUCE.
En caso el trámite de lo ordenado en la presente resolución no concluya con la aprobación de la Autoridad Certificadora por causa imputable al administrado, la medida administrativa se considerará incumplida.','00014732512','20250600120',10.368,NULL,NULL,'ACTIVO'),
	 ('0011-2025-ODES-SMA','MUNICIPALIDAD PROV. BELLAVISTA','00005-2025-OEFA/ODES-SAM','2025-06-30','2025-I24-028735','ACTIVO','Realizar la succión y bombeo de las aguas pluviales acumuladas en la trinchera N°14 en las coordenadas UTM WGS84 326498E 9224955N.','00014372512','20250600109',1,NULL,NULL,'ACTIVO');
INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0011-2025-ODES-SMA','MUNICIPALIDAD PROV. BELLAVISTA','00005-2025-OEFA/ODES-SAM','2025-06-30','2025-I24-028735','ACTIVO','Paralización de toda acción de descarga, y/o acopio, y/o disposición final de residuos sólidos municipales, que se realice fuera de las trincheras de la unidad fiscalizable; considerando que toda descarga y disposición final de los residuos sólidos municipales recolectados, deben realizarse únicamente en las trincheras de disposición final del relleno sanitario.','00014362512','20250600109',1,NULL,NULL,'ACTIVO'),
	 ('0011-2025-ODES-SMA','MUNICIPALIDAD PROV. BELLAVISTA','00005-2025-OEFA/ODES-SAM','2025-06-30','2025-I24-028735','ACTIVO','Realizar el retiro, recolección, transporte y disposición final de la totalidad de los residuos sólidos municipales descargados y acumulados en el acceso principal del relleno sanitario y entre los espacios que separan las trincheras; cuya disposición final deberá realizarse en la trinchera N° 14 del relleno Sanitario.','00014382512','20250600109',1,NULL,NULL,'ACTIVO'),
	 ('0230-2022-DSEM-CHID','PETROLEOS DEL PERU PETROPERU SA','00150-2025-OEFA/DSEM','2025-06-30','2025-I01-028749','ACTIVO','Declarar que Petróleos del Perú - Petroperú S.A. persiste en el incumplimiento de la medida administrativa 4 ordenada mediante el Acta de Medida Preventiva del 22 de septiembre de 2022 y prorrogada mediante la Resolución Nº 0272-2022-OEFA/DSEM del 27 de diciembre de 2022, Nº 0046-2023-OEFA/DSEM del 13 de marzo de 2023 y Nº 0088-2023-OEFA/DSEM del 12 de mayo de 2023, bajo el Expediente Nº 0203-2022-DSEM-CHID.

Imponer a Petróleos del Perú - Petroperú S.A. una multa coercitiva que asciende a treinta y tres con 75/100 (33.75) UIT por el incumplimiento de la medida administrativa 4 ordenada mediante el Acta de Medida Preventiva del 22 de septiembre de 2022 y prorrogada mediante la Resolución Nº 0272-2022-OEFA/DSEM del 27 de diciembre de 2022, Nº 0046-2023-OEFA/DSEM del 13 de marzo de 2023 y Nº 0088-2023-OEFA/DSEM del 12 de mayo de 2023, bajo el Expediente Nº 0203-2022-DSEM-CHID.
','00014392512','20250600110',33.75,NULL,NULL,'ACTIVO'),
	 ('0204-2021-DSEM-CMIN','ACTIVOS MINEROS S.A.C.','00158-2025-OEFA/DSEM','2025-07-14','2025-I01-031206','ACTIVO','Tratar temporalmente el efluente proveniente de la bocamina ID 1464, el cual debe cumplir con los LMP del D.S. N° 010-2010, hasta que se implemente las plantas de tratamiento de acuerdo a lo establecido en el PCPAM Pushaquilca.','00015952512','20250700021',100,NULL,NULL,'ACTIVO'),
