	 ('0204-2021-DSEM-CMIN','ACTIVOS MINEROS S.A.C.','00158-2025-OEFA/DSEM','2025-07-14','2025-I01-031206','ACTIVO','Ejecutar el cierre de la bocamina 5032, de acuerdo a las especificaciones técnicas establecidas en el PCPAM Pushaquilca, a fin de evitar impactos adversos al ambiente.','00015992512','20250700021',64,NULL,NULL,'ACTIVO'),
