	 ('0053-2024-DSIS-CRES',NULL,'00146-2024-OEFA/DSIS','2024-12-30','2024-I01-050485','INACTIVO','Realizar el esparcido, compactación y cobertura diaria de todos los residuos sólidos que se encuentran dispuestos – sin cobertura – en la terraza Nº 1, ocupando un área de 5418 m2, del cual corresponde a tres (3) zonas','00000012412','20250700005',1.65,NULL,NULL,'INACTIVO'),
	 ('0020-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE PUCALA','00015-2025-OEFA/ODES-LAM','2025-07-10','2025-I12-021664','ACTIVO','Medida Preventiva N° 4
