INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0240-2023-DSEM-CHID','PLUSPETROL NORTE S.A.','00296-2025-OEFA/DSEM','2025-12-10','2025-I01-053184','ACTIVO','Asegurar el área afectada detallada en la Tabla N° 1 de la presente resolución (19,589 m2 de suelo y vegetación; y, 906 m2 de agua y sedimentos) donde se verificó la afectación de los componentes ambientales suelo, agua superficial y sedimento e incrementar las barreras mecánicas y/o oleofílicas en las rutas de migración del hidrocarburo, así como en las áreas que continúan siendo afectadas por la migración del contaminante. Asimismo, implementar cuadrillas para el control y mantenimiento de las barreras mecánicas y/o oleofílicas colocadas en las rutas de migración, con la finalidad de que dichas barreras preserven su funcionalidad de contener y recuperar el petróleo crudo derramado en el derecho de vía a la altura de los km 48+401 y km 48+433 del oleoducto Corrientes - Saramuro (T1) del Lote 8.','00046992512','20251200041',3.24,NULL,NULL,'ACTIVO'),
	 ('0240-2023-DSEM-CHID','PLUSPETROL NORTE S.A.','00296-2025-OEFA/DSEM','2025-12-10','2025-I01-053184','ACTIVO','Culminar la limpieza  de la totalidad de las áreas afectadas con presencia de petróleo crudo detalladas en la Tabla N° 1 de la presente resolución (19,589 m2 de suelo y vegetación; y, 906 m2 de agua y sedimentos), donde se verificó la afectación de los componentes ambientales suelo, agua y sedimentos; así como de las áreas que continúan siendo afectadas por la migración del petróleo crudo, como consecuencia de la falta de contención efectiva del petróleo crudo provenientes de las emergencias ambientales ocurridas por los derrames de petróleo crudo en los km48+401 y km 48+433 del oleoducto Corrientes - Saramuro (T1) del Lote 8.','00047002512','20251200041',18,NULL,NULL,'ACTIVO'),
	 ('0240-2023-DSEM-CHID','PLUSPETROL NORTE S.A.','00296-2025-OEFA/DSEM','2025-12-10','2025-I01-053184','ACTIVO','Realizar la disposición final de los residuos sólidos y líquidos peligrosos y no peligrosos generados como consecuencia de las actividades de limpieza y descontaminación de las áreas afectadas por las emergencias ambientales ocurridas por los derrames de petróleo crudo en los km 48+401 y km 48+433 del oleoducto Corrientes - Saramuro (T1) del Lote 8, de acuerdo a las especificaciones normativas del Decreto Supremo N° 014-2017-MINAM, Reglamento del Decreto Legislativo N° 1278, Decreto Legislativo que aprueba la Ley de Gestión Integral de Residuos Sólidos.','00047022512','20251200041',3.24,NULL,NULL,'ACTIVO'),
	 ('0197-2024-DSEM-CMIN','ARUNTANI S.A.C.','00014-2026-OEFA/DSEM','2026-01-15','2026-I01-001460','ACTIVO','Identificar en campo el origen de la tubería ubicada en la coordenada UTM WGS 84 19: 371243 E, 8167473 N.','00001362612','20260100031',64,NULL,NULL,'ACTIVO'),
	 ('0001-2025-DSEM-CMIN','ARUNTANI S.A.C.','00199-2025-OEFA/DSEM','2025-08-22','2025-I01-037127','ACTIVO','Retirar la tubería desde su origen hasta la ubicación de la misma en coordenadas UTM WGA 84 19: 371659 E, 8167196 N, para luego captar el agua de contacto ESP-ARI-1P y derivarla hacia el sistema de tratamiento de agua acida (STTA Wetland Sur), a fin de que cumpla con los LMP aprobado mediante el Decreto Supremo N° 010-2010-MINAM en el punto PS-02 (antes de ser descargado a la quebrada Apostoloni.','00022052512','20250800061',100,NULL,NULL,'ACTIVO'),
	 ('0056-2025-DSEM-CELE',NULL,'00223-2025-OEFA/DSEM','2025-09-24','2025-I01-042112','INACTIVO','“DECLARAR que EMP REG DE SERV PUBLICO DE ELECTRICIDAD
incumplió las medidas preventivas ordenadas mediante el Acta de Supervisión
suscrita el 17 de marzo de 2025, en la unidad fiscalizable Central Termoeléctrica
El Estrecho.
IMPONER a EMP REG DE SERV PUBLICO DE ELECTRICIDAD una multa
coercitiva ascendente a veintidós con 80/100 (22,8) Unidades Impositivas
Tributarias (UIT) por el incumplimiento de las medidas preventivas ordenada
mediante el Acta de Supervisión suscrita el 17 de marzo de 2025.”','00028302512','20250900081',22.8,NULL,NULL,'INACTIVO'),
	 ('0023-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE SAN CLEMENTE','00013-2025-OEFA/ODES-ICA','2025-12-30','2025-I09-047001','ACTIVO','Obligación N°2 (O.2): “Realizar acciones de esparcido, compactación y cobertura con material de la zona, de los residuos sólidos que son descargados en el sector definido para la descarga de los residuos sólidos. Para lo cual, la capa de cobertura deberá tener un espesor mínimo de 0.20 m.
Asimismo, cabe señalar que, durante el plazo de la presente medida, la municipalidad deberá disponer temporal y únicamente sus residuos sólidos en el ADRS “Botadero Sector Caucato”
','00052962512','20251200181',4.5,NULL,NULL,'ACTIVO'),
	 ('0020-2025-ODES-LAM','MUNICIPALIDAD DISTRITAL DE CIUDAD ETEN;MUNICIPALIDAD DISTRITAL DE MONSEFU;MUNICIPALIDAD DISTRITAL DE PIMENTEL;MUNICIPALIDAD DISTRITAL DEL PUERTO ETEN','00002-2026-OEFA/ODES-LAM','2026-02-03','2026-I12-003961','ACTIVO','Medida Preventiva N° 1

Definir y delimitar una única área o sector específico dentro del ADRSM Botadero Municipal Monsefú - Sorrocote, para realizar la descarga diaria de residuos sólidos municipales, para lo cual deben ejecutar las siguientes acciones:

1.1.	Identificar y definir un sector específico al interior del ADRSM para la disposición final de residuos sólidos. Dicha área debe estar identificada con un cartel en la que se detalle: “Área Degradada de Residuos Sólidos – Sector Especifico”. Además, deberá definir una zona de acceso y vía de tránsito para todos los Administrados, la que debe contar con carteles informativos con el siguiente detalle: “Se prohíbe la realización de acciones de segregación y quema de residuos sólidos”. 

Estos carteles deben tener un tamaño razonable para ser vistos desde una larga distancia, estar firmemente anclados al suelo para garantizar su estabilidad y permanencia; asimismo, deben ser diseñados con materiales resistentes y estructuras sólidas para asegurar su durabilidad.

1.2.	Instalar un cerco perimétrico en el sector específico, asegurando su delimitación permanente

1.3.	Se debe realizar la retroalimentación y comunicación al personal que realiza actividades de recojo, manejo y traslado de los residuos sólidos municipales dentro del botadero, sobre:

(i)	El único lugar para realizar la descarga de los residuos sólidos recolectados es en el sector específico.
(ii)	No se puede realizar la descarga de residuos sólidos en zonas distintas a la identificada y delimitada.
','00005442612','20260200007',6.56,NULL,NULL,'ACTIVO'),
	 ('0218-2024-DSAP-CAGR','INTERNATIONAL DONKEY COMPANY SOCIEDAD ANONIMA CERRADA','00009-2026-OEFA/DSAP','2026-02-27','2026-I01-007313','ACTIVO','Cesar el vertimiento e infiltración de los efluentes de la actividad de faenado de ganado équido hacia el río Santa, hasta no acreditar la operatividad y funcionamiento del sistema de tratamiento de efluentes eficaz, de manera que cumpla con los valores establecidos en la Guía Sobre Medio Ambiente, Salud y Seguridad para la producción de carne IFC/BM.
En tanto el administrado no acredite la implementación de un sistema de tratamiento de efluentes eficaz, los efluentes generados en su proceso productivo podrán ser almacenados en el tanque séptico para luego ser dispuestos a través de una EPS o EO- RS autorizadas.
A fin de ejecutar el cese de toda forma de vertimiento e infiltración de efluentes, el administrado debe cumplir con lo siguiente:
 
a)	Sellado con material de concreto y ladrillo, de la conexión de salida del tanque séptico ubicado en las coordenadas UTM WGS84 18L 208156E, 8973894N a fin de almacenar la totalidad de los efluentes generados en la actividad de beneficio de animales de abasto.
El cese de toda forma de vertimiento se mantendrá hasta el que el administrado implemente el sistema de tratamiento de efluentes eficaz, de manera que cumpla con los valores establecidos en la Guía Sobre Medio Ambiente, Salud y Seguridad para la producción de carne IFC/BM.','00012232612','20260200130',12.96,NULL,NULL,'ACTIVO'),
	 ('0218-2024-DSAP-CAGR','INTERNATIONAL DONKEY COMPANY SOCIEDAD ANONIMA CERRADA','00009-2026-OEFA/DSAP','2026-02-27','2026-I01-007313','ACTIVO','Realizar la limpieza del área circundante al tanque séptico por donde discurren los efluentes hacia el río Santa.
 
Los residuos sólidos generados en el proceso de limpieza del área impactada deberán ser dispuestos a través de una Empresa Operadora (EO-RS) autorizada.','00012242612','20260200130',3.2,NULL,NULL,'ACTIVO');
