INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0048-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE EL PORVENIR;MUNICIPALIDAD DISTRITAL DE FLORENCIA DE MORA;MUNICIPALIDAD DISTRITAL DE HUANCHACO;MUNICIPALIDAD DISTRITAL DE LA ESPERANZA;MUNICIPALIDAD DISTRITAL DE MOCHE;MUNICIPALIDAD DISTRITAL DE SALAVERRY;MUNICIPALIDAD DISTRITAL DE VICTOR LARCO HERRERA;MUNICIPALIDAD PROVINCIAL DE TRUJILLO','00114-2024-OEFA/DSIS','2024-10-09','2024-I01-038669','ACTIVO','Obligación 3.1 de la medida preventiva N °3
Elaborar, remitir y ejecutar un Programa de
Vigilancia, para el resguardo y prevención de
ingreso de menores de edad, adultos mayores y
animales; así como, la no realización de acciones
de quema de residuos sólidos en el interior del
ADRS Botadero El Milagro.
3.1 Elaborar y remitir al OEFA un Programa de
Vigilancia, para el resguardo y prevención,
respecto a la prohibición de ingreso de
menores de edad, adultos mayores y
animales; así como, de la prohibición de
realización de acciones de quema de
residuos sólidos en el ADRS “Botadero El
Milagro”.
Dicho Programa de Vigilancia, deberá
considerar las acciones que formarán parte
de la vigilancia, resguardo y prevención,
respecto a la prohibición de ingreso de
menores de edad, adultos mayores y
animales; así como de la prohibición de
realización de acciones de quema de
residuos sólidos, por parte de terceros
(recicladores), u otra persona que tenga
acceso e ingreso a la mencionada ADRS.
Asimismo, la vigilancia deberá considerar el
resguardo con efectivos, tanto policiales, de
seguridad ciudadana, u otro personal que las
municipalidades consideren. Culminado el
plazo, el OEFA evaluará si existe la
necesidad de ampliar y continuar con la
vigilancia, sin perjuicio de que las
municipalidades puedan considerar y
efectuar coordinaciones y/o apoyo de
efectivos policiales, o con áreas de
seguridad ciudadana de sus respectivas
comunas.
(…)','00001322412','20260600043',5,NULL,NULL,'ACTIVO'),
	 ('0241-2021-DSEM-CHID','PLUSPETROL NORTE S.A.','00088-2026-OEFA/DSEM','2026-04-29','2026-I01-016745','ACTIVO','Almacenar y transportar los residuos sólidos y líquidos peligrosos y no peligrosos generados como producto de las actividades de limpieza y descontaminación del área afectada por la emergencia ambiental ocurrida en línea de forros de 4” del pozo PAV 34, ubicada en el yacimiento Pavayacu del Lote 8, de acuerdo con las especificaciones técnicas previstas en el Decreto Supremo N° 014-2017-MINAM, Reglamento del Decreto Legislativo N° 1278, Decreto Legislativo que aprueba la Ley de Gestión Integral de Residuos Sólidos.','00022932612','20260400115',23.04,NULL,NULL,'ACTIVO'),
