INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0284-2022-DSEM-CHID','PLUSPETROL NORTE S.A.','00125-2026-OEFA/DSEM','2026-07-08','2026-I01-028325','ACTIVO','PPN no cumplió con la medida preventiva N.° 3 ordenada mediante la Resolución N.° 0204-2022-OEFA/DSEM, toda vez que se mantiene pendiente la limpieza del componente ambiental suelo en las áreas N.° 1 (extendida) y N.° 5, de acuerdo con el siguiente detalle:

¿	El Área N.° 1 (extendida) de 250 m², la cual corresponde al área extendida en la primera acción de supervisión (48 m2) y segunda acción de supervisión (202 m2), en las que se advirtió superación a los valores establecidos en los ECA para Suelo 2013, en los parámetros Fracciones de hidrocarburos (F2) y Naftaleno. 
 
¿	El Área N.° 5 de 17 m², donde durante la segunda acción de supervisión se advirtió superación al ECA para Suelo 2013 en el parámetro Plomo Total.

','00037822612','20260700021',18,NULL,NULL,'ACTIVO'),
	 ('0284-2022-DSEM-CHID','PLUSPETROL NORTE S.A.','00125-2026-OEFA/DSEM','2026-07-08','2026-I01-028325','ACTIVO','PPN no cumplió con la medida preventiva N.° 4 ordenada mediante la Resolución N.° 0204-2022-OEFA/DSEM, toda vez que, de los hechos constatados en la primera y segunda acción de verificación de medida, se verificó que no se ha efectuado el retiro de veinte (20) marcos tipo «H» en desuso en las Áreas Nros. 1, 2, 3, 4, 5 y 6, de acuerdo con las especificaciones técnicas del Decreto Supremo N.° 014-2017-MINAM, Reglamento del Decreto Legislativo N.° 1278, Decreto Legislativo que aprueba la Ley de Gestión Integral de Residuos Sólidos y sus instrumentos de gestión ambientales aplicables.','00037832612','20260700021',11.52,NULL,NULL,'ACTIVO'),
