INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0049-2025-ODES-TUM','MUNICIPALIDAD DISTRITAL DE AGUAS VERDES;MUNICIPALIDAD DISTRITAL DE PAPAYAL;MUNICIPALIDAD PROVINCIAL ZARUMILLA','00001-2026-OEFA/ODES-TUM','2026-04-15','2026-I20-000562','ACTIVO','Medida preventiva N° 1 
Realizar con una frecuencia mínima de dos (2) veces por semana y de forma permanente las operaciones de esparcido, nivelación, compactación y cobertura de los residuos sólidos dispuestos en el área específica  del ADRSM Botadero Municipal, con material de cobertura de la zona, con un espesor mínimo de 0.20 m, para lo cual deberá:

¿	Delimitar el área específica mediante estacas y/o hitos de madera de 2 m de altura, según las coordenadas del Cuadro N°01 de la presente resolución.
¿	Instalar un (01) cartel informativo y dos (02) carteles prohibitivos.
¿	Realizar las acciones de descarga y disposición final de los residuos sólidos únicamente en el área específica del ADRSM, para lo cual deberá implementar un cronograma para ejecutar las acciones de esparcido, nivelación, compactación y cobertura de los residuos sólidos municipales.','00018662612','20260400027',6.3,NULL,NULL,'ACTIVO'),
	 ('0061-2024-ODES-UCA','MUNICIPALIDAD DISTRITAL DE IRAZOLA','00005-2026-OEFA/ODES-UCA','2026-07-15','2026-I27-029580','ACTIVO','Medida Preventiva N° 02

Realizar la descarga, esparcido, nivelación, compactación y cobertura de los residuos sólidos que ingresan diariamente al ADRS “Botadero Sector Caserío Nuevo Huánuco, únicamente en el sector definido por la municipalidad. 

Las operaciones de   esparcido, nivelación, compactación y cobertura de los residuos sólidos deberán realizarse al menos dos (02) veces al mes, considerando una capa de cobertura de mínimo 0.2m, de espesor. ','00038542612','20260700037',3,NULL,NULL,'ACTIVO'),
	 ('0048-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE EL PORVENIR;MUNICIPALIDAD DISTRITAL DE FLORENCIA DE MORA;MUNICIPALIDAD DISTRITAL DE HUANCHACO;MUNICIPALIDAD DISTRITAL DE LA ESPERANZA;MUNICIPALIDAD DISTRITAL DE MOCHE;MUNICIPALIDAD DISTRITAL DE SALAVERRY;MUNICIPALIDAD DISTRITAL DE VICTOR LARCO HERRERA;MUNICIPALIDAD PROVINCIAL DE TRUJILLO','00114-2024-OEFA/DSIS','2024-10-09','2024-I01-038669','ACTIVO','Obligación 1.2 de la medida preventiva N° 1
Prohibir y cesar de inmediato de toda forma y
acción de quema de residuos sólidos, por parte del
personal directo o terceros (recicladores
informales) al interior del ADRS “Botadero El
Milagro”.
Para lo cual, las municipalidades deberán
acreditar la ejecución de las siguientes acciones:
(…)
1.2 Ejecutar la prohibición y cese de toda forma de
acción de quema de residuos sólidos, ya sea
por parte de personal directo, o terceros, en el
interior del ADRS “Botadero El Milagro”.
*Para el desarrollo de las capacitaciones y/o
inducciones a los recicladores presentes en el
ADRS “Botadero El Milagro”, las municipalidades
podrán coordinar y/o gestionar el apoyo y/o
asesoría técnica correspondiente a instituciones
con competencia en materia de residuos sólidos.','00000922412','20260600043',5,NULL,NULL,'ACTIVO'),
