INSERT INTO SISUD.VW_MULTA_COERCITIVA (NUMERO_EXPEDIENTE,ADMINISTRADO,RESOLUCION,FECHA_EMISION,NUMERO_REGISTRO,ESTADO_RESOLUCION,MEDIDA_ADMINISTRATIVA,CUM,CAM,MONTO_MULTA,MONTO_MULTA_REC,MONTO_MULTA_TFA,ESTADO_MULTA) VALUES
	 ('0015-2024-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE SANTA ROSA','00006-2026-OEFA/ODES-LAM','2026-04-22','2026-I12-015660','ACTIVO','
La MD Santa Rosa no realizó las operaciones de esparcido, compactación y cobertura de los residuos sólidos dispuestos a cielo abierto en el ADRSM Botadero Municipal Santa Rosa Sector Laguna Chica en zonas distintas al área o sector definido señalado en el Oficio N° 313-2024-MDSR/A de fecha 23 de setiembre de 2024; teniendo en cuenta lo siguiente:

a) Realizó fuera de plazo la sectorización de las zonas del ADRSM, distintas al área o sector definido señalado en el Oficio N° 313-2024-MDSR/A ADRSM.

b) Elaboró fuera de plazo un cronograma de implementación, para ejecutar las acciones de esparcido, compactación y cobertura de las zonas del ADRSM, distintas al área o sector definido señalado en el Oficio N 313-2024-MDSR/A ADRSM.

c) No realizó el esparcido, compactación y cobertura de los residuos sólidos, con un espesor entre 0.20 a 0.30 m, de las zonas del ADRSM. distintas al área o sector definido señalado en el Oficio N 313-2024-MDSR/A ADRSM; esto conforme al cronograma de implementación previamente elaborado por la municipalidad y aprobado por el OEFA.','00021022612','20260400078',2.6,NULL,NULL,'ACTIVO'),
	 ('0159-2025-DSEM-CMIN','COMPAÑIA DE MINAS BUENAVENTURA S.A.A.','00087-2026-OEFA/DSEM','2026-04-29','2026-I01-016763','ACTIVO','Elaborar estudios especializados en los sectores 1 (aledaño a la bocamina Nv. 4720) y 2 (noroeste del depósito de desmonte principal Nv. 4725) con la finalidad de determinar las zonas de saturación y migración de aguas subterráneas acumuladas (aguas de contacto) en las galerías Nv. 4720 y Nv. 4600, que afloraron en los puntos ESP-ARI-1, ESP-ARI-2, ESP-ARI-3, ESP-ARI-4, ESP-ARI-5 y ESP-AS-4, identificados en la acción de supervisión noviembre 2023 y acción de supervisión julio 2024
Dichos estudios deberán tener en cuenta las consideraciones mencionadas en el párrafo 126 de la presente resolución.','00022782612','20260400113',32,NULL,NULL,'ACTIVO'),
	 ('0089-2021-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE IMPERIAL','00047-2022-OEFA/DSIS','2022-09-30','2022-I01-036203','ACTIVO','Realizar en el sector definido, las actividades de nivelación, compactación y
