','00018552612','20260400022',23.04,NULL,NULL,'ACTIVO'),
	 ('0081-2023-DSIS-CRES','MUNICIPALIDAD DISTRITAL DE SANTIAGO','00103-2023-OEFA/DSIS','2023-11-30','2023-I01-047077','ACTIVO','Implementar las operaciones de nivelación, compactación y cobertura
diaria de los residuos sólidos en el frente de trabajo de las trincheras
