	 ('0018-2026-DSEM-CMIN','ARUNTANI S.A.C.','00114-2026-OEFA/DSEM','2026-06-22','2026-I01-025348','ACTIVO','Reconformar la zona deslizada del tajo Valle para evitar la generación de drenaje acido de mina y restablecer los canales de manejo de aguas superficiales.','00033432612','20260600105',87.5,NULL,NULL,'ACTIVO'),
	 ('0045-2022-DSIS-CRES','MUNICIPALIDAD PROVINCIAL DE HUAYLAS','00025-2022-OEFA/DSIS','2022-07-14','2022-I01-025162','ACTIVO','Implementar los drenes de lixiviados exteriores a lo largo del pie del talud
